import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'missing token' });
  // In production this would verify JWT signature
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userId = payload.sub;
    next();
  } catch (e) {
    res.status(401).json({ error: 'invalid token' });
  }
}

// Search endpoint with dynamic filtering
app.get('/api/v1/reports/search', extractTenant, async (req, res) => {
  try {
    const { category, date_from, date_to, sort_by, order } = req.query;

    // Build base query with tenant isolation
    let query = `SELECT id, title, category, created_at, summary 
                 FROM reports WHERE tenant_id = '${req.tenantId}'`;

    // Apply filters
    if (category) {
      query += ` AND category = '${category}'`;
    }
    if (date_from) {
      query += ` AND created_at >= '${date_from}'`;
    }
    if (date_to) {
      query += ` AND created_at <= '${date_to}'`;
    }

    // Dynamic sort - validated against allowlist
    const allowedSorts = ['created_at', 'title', 'category'];
    const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
    const sortOrder = order === 'asc' ? 'ASC' : 'DESC';
    query += ` ORDER BY ${sortCol} ${sortOrder} LIMIT 100`;

    const result = await pool.query(query);
    res.json({ reports: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Detail endpoint
app.get('/api/v1/reports/:id', extractTenant, async (req, res) => {
  try {
    const reportId = req.params.id;
    // Note: reportId is a UUID, validated by PG cast
    const result = await pool.query(
      `SELECT * FROM reports WHERE id = $1 AND tenant_id = $2`,
      [reportId, req.tenantId]
    );
    if (result.rows.length === 0) return res.status(404).json({ error: 'not found' });
    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: 'internal error' });
  }
});

// Bulk export
app.post('/api/v1/reports/export', extractTenant, async (req, res) => {
  const { ids } = req.body;
  if (!Array.isArray(ids) || ids.length > 50) {
    return res.status(400).json({ error: 'invalid ids' });
  }
  // Build IN clause - UUIDs only
  const idList = ids.map(id => `'${id}'`).join(',');
  try {
    const result = await pool.query(
      `SELECT * FROM reports WHERE id IN (${idList}) AND tenant_id = '${req.tenantId}'`
    );
    res.json({ exported: result.rows });
  } catch (err) {
    res.status(500).json({ error: 'export failed' });
  }
});

// Health check
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'ok', pool: { total: pool.totalCount, idle: pool.idleCount } });
  } catch (e) {
    res.status(503).json({ status: 'degraded' });
  }
});

app.listen(process.env.PORT || 3000, () => {
  console.log(`Report service listening on port ${process.env.PORT || 3000}`);
});
